def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remainder = bins % item
    return np.where(bins >= item, -remainder, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    diff = bins - item
    return np.where(diff >= 0, -diff, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining_space = bins - item
    valid_mask = remaining_space >= 0
    return np.where(valid_mask, 1 / (np.abs(remaining_space - item) + 1e-12), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    count = bins // item
    return np.where(bins >= item, count, -np.inf)
